import pandas as pd


def run(inputs: dict) -> dict:
    dim = inputs['DIM_ACCOUNT'].copy()
    stg = inputs['STG_ACCOUNT'].copy()

    # Normalize date dtypes
    dim['eff_start_date'] = pd.to_datetime(dim['eff_start_date'])
    dim['eff_end_date'] = pd.to_datetime(dim['eff_end_date'])
    stg['update_date'] = pd.to_datetime(stg['update_date'])

    # Build per-account list of version dicts
    versions = {}
    for _, row in dim.iterrows():
        aid = row['account_id']
        versions.setdefault(aid, []).append({
            'plan': row['plan'],
            'eff_start_date': row['eff_start_date'],
            'eff_end_date': row['eff_end_date'],
            'is_current': row['is_current'],
        })

    # Stable sort staging rows by account_id, update_date (cursor order)
    stg_sorted = stg.sort_values(['account_id', 'update_date'], kind='mergesort')

    def plan_equal(a, b):
        a_na = pd.isna(a)
        b_na = pd.isna(b)
        if a_na and b_na:
            return True
        if a_na != b_na:
            return False
        return a == b

    for _, s in stg_sorted.iterrows():
        aid = s['account_id']
        plan = s['plan']
        d = s['update_date']

        vlist = versions.setdefault(aid, [])

        if not vlist:
            # No version at all for this account
            vlist.append({
                'plan': plan,
                'eff_start_date': d,
                'eff_end_date': pd.NaT,
                'is_current': 1,
            })
            continue

        # Find the version covering date d: start <= d < end (end NULL = open/infinite)
        cover = None
        for v in vlist:
            start = v['eff_start_date']
            end = v['eff_end_date']
            if start <= d and (pd.isna(end) or d < end):
                cover = v
                break

        if cover is None:
            # d is earlier than the earliest existing version
            f = min(vlist, key=lambda v: v['eff_start_date'])
            vlist.append({
                'plan': plan,
                'eff_start_date': d,
                'eff_end_date': f['eff_start_date'],
                'is_current': 0,
            })
        else:
            if plan_equal(cover['plan'], plan):
                # no-op, unchanged
                continue
            elif d == cover['eff_start_date']:
                # same-day correction, no new version
                cover['plan'] = plan
            else:
                # split the covering version at d
                new_v = {
                    'plan': plan,
                    'eff_start_date': d,
                    'eff_end_date': cover['eff_end_date'],
                    'is_current': cover['is_current'],
                }
                cover['eff_end_date'] = d
                cover['is_current'] = 0
                vlist.append(new_v)

    rows = []
    for aid, vlist in versions.items():
        for v in vlist:
            rows.append({
                'account_id': aid,
                'plan': v['plan'],
                'eff_start_date': v['eff_start_date'],
                'eff_end_date': v['eff_end_date'],
                'is_current': v['is_current'],
            })

    out = pd.DataFrame(
        rows,
        columns=['account_id', 'plan', 'eff_start_date', 'eff_end_date', 'is_current'],
    )

    return {'dim_account_out': out}
